(()=>{const t=document.querySelector(".side nav"),n=document.getElementById("releaseNav");if(t&&!document.getElementById("postShipmentNav")){const e=document.createElement("a");e.id="postShipmentNav",e.href="#pos-embarque",e.hidden=!0,e.innerHTML="◷ &nbsp; Pós-embarque",t.insertBefore(e,n?.nextSibling||null)}const o=document.querySelector(".shell main"),s=document.getElementById("followupPage");if(o&&!document.getElementById("postShipmentPage")){const e=document.createElement("section");e.id="postShipmentPage",e.hidden=!0,e.innerHTML='<div class="top"><div><p class="eyebrow">Operação de exportação</p><h1>Pós-embarque</h1></div><button class="btn secondary" id="closePostShipmentBtn" type="button">← Processos</button></div><p class="intro">Registre e acompanhe a data de embarque de cada processo.</p><div class="field compact-filter"><label for="postShipmentFilterSelect">Filtrar processos</label><select id="postShipmentFilterSelect"><option value="all">Todos os processos</option><option value="pending">Sem data de embarque</option><option value="shipped">Com data de embarque</option></select></div><div id="postShipmentList" class="panel scrollable-panel"></div>',o.insertBefore(e,s||null)}})();
